-- Places added by hand from Plus Codes looked up on Google Maps (ancien.csv).
-- Generated by supabase/tools/places_from_plus_codes.py; positions are the
-- centres of the codes (about 14 m). Safe to run again: a place already there
-- under the same name is left alone. Generated 2026-11-16.

-- Douala: 1 places
insert into public.landmarks (city_id, name, aliases, location, kind, source)
select c.id, v.name, v.aliases,
       extensions.st_setsrid(extensions.st_makepoint(v.lng, v.lat), 4326)::extensions.geography,
       v.kind, 'manual'
from public.cities c, (values
  ('Ancien Troisième', array['Ancien 3eme', 'Ancien 3ème']::text[], 4.043038, 9.704078, 'place=locality')
) as v(name, aliases, lat, lng, kind)
where c.name = 'Douala'
on conflict (city_id, name) do nothing;

-- These searches are answered now: clear them from the missing list.
delete from public.search_misses where query in ('ancien troiseme', 'ancien troisième');

-- Riders who asked for them (searched with notifications on, or used
-- 'Tell us about it') are linked to the new place; the notify function
-- tells them it is on Kombien at its next run.
update public.place_requests r
   set status = 'added', landmark_id = l.id
  from (values
  ('ancien troisième', 'Douala', 'Ancien Troisième'),
  ('ancien troiseme', 'Douala', 'Ancien Troisième')
  ) as v(query, city, name)
  join public.cities c on c.name = v.city
  join public.landmarks l on l.city_id = c.id and l.name = v.name
 where r.status = 'open'
   and lower(r.name) = v.query
   and (r.city = '' or lower(r.city) = lower(v.city));
